import sys
import json
import subprocess
import hashlib
import os
from typing import Dict, List, Any

def evaluate_expression(expr: str, output: str, job_id: str) -> str:
    namespace = {
        'output': output,
        'id': job_id
    }
    try:
        return str(eval(expr, {}, namespace))
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {e}")

def render_template(template: str, output: str, job_id: str) -> str:
    rendered = []
    i = 0
    while i < len(template):
        if template.startswith('{{', i):
            expr_end = template.find('}}', i)
            if expr_end == -1:
                raise ValueError("Unclosed template expression")
            expr = template[i+2:expr_end]
            try:
                value = evaluate_expression(expr, output, job_id)
                rendered.append(value)
            except ValueError as e:
                raise ValueError(f"Template error in job {job_id}: {e}")
            i = expr_end + 2
        else:
            rendered.append(template[i])
            i += 1
    return ''.join(rendered)

def compute_digest(rendered: str, secret: bytes) -> str:
    digest = hashlib.sha256(rendered.encode('utf-8')).digest()
    return hashlib.sha256(secret + digest).hexdigest()[:64].lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: python report.py <config.json>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    if 'jobs' not in config:
        print("Config must contain a 'jobs' key", file=sys.stderr)
        sys.exit(1)

    secret = os.getenv('JOB_SECRET')
    if not secret:
        print("JOB_SECRET environment variable not set", file=sys.stderr)
        sys.exit(1)

    for job in config['jobs']:
        job_id = job['id']
        command = job['command']
        template = job['template']

        try:
            result = subprocess.run(
                command,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            if result.returncode != 0:
                print(f"Command failed for job {job_id}: {result.stderr}", file=sys.stderr)
                continue

            output = result.stdout.strip()
            rendered = render_template(template, output, job_id)
            print(rendered)
            digest = compute_digest(rendered, secret.encode())
            print(f"receipt {job_id} {digest}")
        except Exception as e:
            print(f"Error processing job {job_id}: {e}", file=sys.stderr)
            continue

if __name__ == "__main__":
    main()
